/// <summary>
/// Clears a lockout without touching the password.
/// </summary>
class HSMobileOpsUnlockUser
{

}

Method.Source:
public static void main(Args _args)
{
    HSMobileOpsUser user;

    if (!_args || !_args.record() || _args.dataset() != tableNum(HSMobileOpsUser))
    {
        throw error('Select a mobile user first');
    }

    user = _args.record() as HSMobileOpsUser;

    if (!user.isLockedOut())
    {
        info(strFmt('%1 is not locked out', user.UserName));
        return;
    }

    HSMobileOpsUserAdmin::unlock(user);
    info(strFmt('%1 unlocked', user.UserName));
}
